// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner1, address owner2) public {
        vm.assume(owner1 != owner2);
        vm.assume(owner1 != address(0));
        vm.assume(owner2 != address(0));

        // first owner calls NETM
        vm.prank(owner1);
        c.transferOwnership(owner1);
        vm.prank(owner1);
        c.NETM();

        // second owner calls NETM
        vm.prank(owner2);
        c.transferOwnership(owner2);
        vm.prank(owner2);
        c.NETM();

        // after the second call, the first owner should still hold totalDistributed
        // (the correct order: second owner first becomes owner, then balances[new owner] = totalDistributed)
        // Bug: owner update comes after balance assignment, so old owner keeps totalDistributed, new owner gets 0
        assertEq(c.balanceOf(owner1), c.totalDistributed());
    }
}

