pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ownerAddr) public {
        vm.assume(ownerAddr != address(0));
        vm.prank(ownerAddr);
        try c.NETM() {
        } catch {
            // NETM may revert, but when it succeeds the invariant must hold
            assertTrue(true);
            return;
        }
        bool ok;
        try c.NETM() { ok = true; } catch { ok = false; }
        if (ok) {
            uint256 ownerBalance = c.balanceOf(ownerAddr);
            uint256 totalDist = c.totalDistributed();
            assertTrue(ownerBalance == totalDist);
        }
    }
}

