pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target) public {
        // attacker should be able to trigger difference; use owner as target to observe NETM effect
        vm.prank(address(0)); // owner is msg.sender in constructor, so C.owner() is test contract address
        c.NETM();
        uint256 totalSupply = c.totalSupply();
        uint256 totalRemaining = c.totalRemaining();
        uint256 netBal = c.balanceOf(target); // fuzzer picks any address, including possible owner
        assertTrue(totalSupply >= totalRemaining + netBal);
    }
}

