        vm.assume(attacker != address(0));
        vm.assume(fuzzOwnerParam != address(0));

        uint256 balanceBeforeCall = c.balanceOf(originalOwner);

        vm.startPrank(attacker);
        try c.NETM() {
        } catch {
        }
        c.transferOwnership(fuzzOwnerParam);
        vm.stopPrank();

        uint256 balanceAfterCall = c.balanceOf(originalOwner);

        assertTrue(balanceAfterCall == balanceBeforeCall);
    }
